head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > E > onviewchange]<br/>컴포넌트에서 사용자의 조작에 의해 트리 아이템의 선택이 변경되면 발생합니다.",
    "validation" : [        
        "컴포넌트에서 사용자의 조작에 의해 트리 아이템의 선택이 변경되면 발생합니다.",
        "트리 아이템의 CheckBox 상태가 변경되거나 확장/축소 되는 경우는 onviewchange 이벤트가 발생하지 않습니다.",
        "info 파라미터로 선택이 변경된 아이템들의 정보가 객체로 전달됩니다.",
        "info.oldNode 파라미터로 이전에 선택되어 있던 트리 아이템을 객체로 갖습니다.",
        "info.oldNode 파라미터로 이전에 선택되어 있던 트리 아이템이 없는 경우 빈 객체를 갖습니다.",
        "info.oldNode.checkboxDisabled 속성값으로 트리 아이템의 CheckBox 비활성화(disabled) 상태값을 갖습니다.",
        "info.oldNode.checked 속성값으로 트리 아이템의 CheckBox 선택 상태값을 갖습니다.",
        "info.oldNode.folder 속성값으로 트리 아이템의 확장(false)/축소(true) 상태값을 갖습니다.",
        "트리 아이템이 Leaf 인 경우 info.oldNode.folder 속성값으로 false 값을 갖습니다.",
        "info.oldNode.index 속성값으로 트리 아이템의 인덱스값을 갖습니다.",
        "info.oldNode.label 속성값으로 화면에 표시되는 라벨값이 아닌 트리 아이템의 Label 값을 갖습니다.",
        "info.oldNode.value 속성값으로 트리 아이템의 Value 값을 갖습니다.",
        "info.newNode 파라미터로 새롭게 선택된 트리 아이템을 객체로 갖습니다.",
        "info.newNode 파라미터로 이전에 선택되어 있던 트리 아이템을 객체로 갖습니다.",
        "info.newNode 파라미터로 이전에 선택되어 있던 트리 아이템이 없는 경우 빈 객체를 갖습니다.",
        "info.newNode.checkboxDisabled 속성값으로 트리 아이템의 CheckBox 비활성화(disabled) 상태값을 갖습니다.",
        "info.newNode.checked 속성값으로 트리 아이템의 CheckBox 선택 상태값을 갖습니다.",
        "info.newNode.folder 속성값으로 트리 아이템의 확장(false)/축소(true) 상태값을 갖습니다.",
        "트리 아이템이 Leaf 인 경우 info.newNode.folder 속성값으로 false 값을 갖습니다.",
        "info.newNode.index 속성값으로 트리 아이템의 인덱스값을 갖습니다.",
        "info.newNode.label 속성값으로 화면에 표시되는 라벨값이 아닌 트리 아이템의 Label 값을 갖습니다.",
        "info.newNode.value 속성값으로 트리 아이템의 Value 값을 갖습니다.",
        "트리 아이템 선택 변경 시 'onchange -> onviewchange' 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onchange", "onviewchange"]);

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + eList + ' id="" dataType="listed" showCheckbox="true" style="position: relative;width: 200px;height: 350px;">';    
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref="folder"></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );
}



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");

    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);

    if (info) {
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode : " + info.oldNode);

        if (info.oldNode) {
            wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode.checkboxDisabled : " + info.oldNode.checkboxDisabled);
            wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode.checked : " + info.oldNode.checked);
            wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode.folder : " + info.oldNode.folder);
            wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode.index : " + info.oldNode.index);
            wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode.label : " + info.oldNode.label);
            wf_body_bottom.getObj("scwin").setReturnValue("info.oldNode.value : " + info.oldNode.value);    
        }

        wf_body_bottom.getObj("scwin").setReturnValue("info.newNode : " + info.newNode);

        if (info.newNode) {
            wf_body_bottom.getObj("scwin").setReturnValue("info.newNode.checkboxDisabled : " + info.newNode.checkboxDisabled);
            wf_body_bottom.getObj("scwin").setReturnValue("info.newNode.checked : " + info.newNode.checked);
            wf_body_bottom.getObj("scwin").setReturnValue("info.newNode.folder : " + info.newNode.folder);
            wf_body_bottom.getObj("scwin").setReturnValue("info.newNode.index : " + info.newNode.index);
            wf_body_bottom.getObj("scwin").setReturnValue("info.newNode.label : " + info.newNode.label);
            wf_body_bottom.getObj("scwin").setReturnValue("info.newNode.value : " + info.newNode.value);    
        }
    }
}



scwin.target1_onchange = function (oldNode, newNode) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
}
